def search_all(max_solutions=1000, node_cap=2000000):
    sols=[]; nodes=0
    for ati, amat in anchor:
      amask=mat_mask(amat,0,0)
      arec=(ati,0,0,amask,amat)
      def dfs(used, remaining, chosen):
        nonlocal nodes
        nodes+=1
        if nodes>node_cap or len(sols)>=max_solutions: return
        if not remaining:
          if used==full: sols.append(chosen.copy())
          return
        # find uncovered cell with fewest viable choices total
        avail=full^used
        bestopts=None; bestcell=None
        bits=avail
        while bits:
          low=bits&-bits; idx=low.bit_length()-1; bits-=low
          opts=[]
          for color in remaining:
            for rec in bycell[color][idx]:
              if rec[3]&used==0: opts.append((color,rec))
          if not opts: return
          if bestopts is None or len(opts)<len(bestopts):
            bestopts=opts;bestcell=idx
            if len(opts)==1: break
        for color,rec in bestopts:
          dfs(used|rec[3], tuple(x for x in remaining if x!=color), chosen+[(color,rec)])
      dfs(amask,(2,3,8),[(7,arec)])
    return sols,nodes
